proguardAdditions.insert:

-keep class com.taptap.sdk.relation.lite.** { *; }
-keep interface com.taptap.sdk.relation.lite.** { *; }
-keep class com.taptap.sdk.relation.lite.unity.** { *; }
-keepclassmembers class com.taptap.sdk.relation.lite.unity.** { *; }
-keepclasseswithmembernames class * { native <methods>; }

gameActivityClassAdditions.insert:

private BridgeRelationLiteServiceImpl mRelationLiteService;

private BridgeRelationLiteServiceImpl getRelationLiteService() {
    if (mRelationLiteService == null) { mRelationLiteService = new BridgeRelationLiteServiceImpl(); }
    return mRelationLiteService;
}

public void routeToTapRelationLite(String requestJson, EngineBridgeCallback callback) {
    try {
        org.json.JSONObject req = new org.json.JSONObject(requestJson);
        String method  = req.getString("method");
        String argsStr = req.optString("args", "");
        switch (method) {
            case "inviteGameByRelationLite":
                getRelationLiteService().inviteGameByRelationLite();
                break;
            case "inviteTeam":
                getRelationLiteService().inviteTeam(new org.json.JSONObject(argsStr).getString("relationLiteTeamId"));
                break;
            case "showTapUserProfile": {
                org.json.JSONObject a = new org.json.JSONObject(argsStr);
                getRelationLiteService().showTapUserProfile(a.getString("relationLiteOpenId"), a.getString("unionId"));
                break;
            }
            case "getFriendsList":
                getRelationLiteService().getFriendsList(
                    new org.json.JSONObject(argsStr).optString("friendListNextPageToken", ""), callback);
                break;
            case "getFollowingList":
                getRelationLiteService().getFollowingList(
                    new org.json.JSONObject(argsStr).optString("followingListNextPageToken", ""), callback);
                break;
            case "getFansList":
                getRelationLiteService().getFansList(
                    new org.json.JSONObject(argsStr).optString("fansListNextPageToken", ""), callback);
                break;
            case "syncRelationshipWithOpenId": {
                org.json.JSONObject a = new org.json.JSONObject(argsStr);
                getRelationLiteService().syncRelationshipWithOpenId(
                    a.getInt("syncRelationAction"), a.optString("nickname",""),
                    a.optString("friendNickname",""), a.optString("friendOpenId",""), callback);
                break;
            }
            case "syncRelationshipWithUnionId": {
                org.json.JSONObject a = new org.json.JSONObject(argsStr);
                getRelationLiteService().syncRelationshipWithUnionId(
                    a.getInt("syncRelationAction"), a.optString("nickname",""),
                    a.optString("friendNickname",""), a.optString("friendUnionId",""), callback);
                break;
            }
            case "registerRelationLiteCallback":
                getRelationLiteService().registerRelationLiteCallback(callback);
                break;
            case "unregisterRelationLiteCallback":
                getRelationLiteService().unregisterRelationLiteCallback();
                break;
            case "registerRelationLiteInviteCallback":
                getRelationLiteService().registerRelationLiteInviteCallback(callback);
                break;
            case "unregisterRelationLiteInviteCallback":
                getRelationLiteService().unregisterRelationLiteInviteCallback();
                break;
            default:
                android.util.Log.w("TapSDK_UE", "TapRelationLite: unknown method: " + method);
        }
    } catch (Exception e) {
        android.util.Log.e("TapSDK_UE", "TapRelationLite route error: " + e.getMessage(), e);
    }
}
